          "body": "<b>社会资本</b>指的是邻里、社区、志愿网络之间那份信任与互助能力。台风来临时，平时就互相搭把手的社区，往往能更快自发组织排水、转运、看护老人；而关系疏离、各自为政的地方，哪怕硬件不差，也可能在信息断点和信任缺口上吃大亏。防灾的真正底座，是人与人之间的联系。",
