      "title": "我国首部《反网络暴力法》公开征求意见，明确平台责任、最高可罚1000万元",
      "source": "新华网",
      "url": "https://www.news.cn/legal/20260804/b8bde4f04d114dfcaad41cbea1f3f446/c.html",
