      "essayQuote": "按键伤人之所以需要专门立法，是因为匿名的键盘放大了人性的幽暗，也让伤害从一句吐槽变成可以量罪的暴力。自由从不意味着可以随意践踏他人尊严，规则的迟到不该成为纵容的理由。当平台被明确戴上责任的镣铐、最高千万罚单亮出牙齿，网络才有望从丛林回到公共空间——管住乱象，恰恰是为了守住每个人说话的权利。"
