      "essayQuote": "利息从“3时代”滑到“1时代”，人们紧握存款的手却没松开。低利率想唤醒的从来不是钱包，而是信心；而当收入预期与投资渠道都偏谨慎，那笔钱便成了不确定时代里唯一确定的安全垫。真正值得追问的，不是钱该放哪，而是一个社会怎样让人敢花、敢投、敢把未来托付出去。"
