          "lens": "他者化",
          "lensId": "othering",
          "body": "<b>他者化</b>指的是把某一群体标记为“外人”、用刻板眼神与手势将其排除在平等尊重之外。机场安保的“拉眼角”动作，并非孤立失礼，而是把中国游客悄然框定为“低人一等”的异类——当歧视披上“服务”的外衣，伤害的就不只是一位乘客，而是整群人的尊严。",
