          "body": "<b>全球化</b>把人流、物流、资本连成一张密网，中国人也成了全球流动的主力客群；但流动越频繁，文化差异与在地偏见就越容易在边检、海关、服务台这些“权力节点”上碰撞。跨国旅游的便利，并不能自动兑换成平等的对待——流动的红利与风险的分布，从来都不均匀。",
