      "id": 9,
      "title": "四大行5年期大额存单全面“返场”：最高利率1.6%，距集体下架不到一年",
      "source": "央视财经",
      "url": "https://ysxw.cctv.cn/article.html?toc_style_id=feeds_default&item_id=14054440975839551652",
      "kicker": "经济 · 经济学",
      "gist": "继中行、农行、建行之后，工商银行8月1日跟进上架两款5年期个人大额存单（年化1.60%和1.55%，20万元起存、可转让），四大行5年期大额存单全面返场、最高利率齐平1.6%；这是国有大行自2025年11月集体下架该产品以来时隔近一年的首次回归，股份行同类产品最高达1.8%，被解读为银行锁定长期负债、缓解久期错配的阶段性选择。",
      "thread": [
        {
          "t": "全面返场",
          "x": "工行8月1日上架两款5年期大额存单（1.60%、1.55%，20万元起存、可转让），四大行5年期产品全部回归，最高利率齐平1.6%。"
        },
        {
          "t": "曾集体下架",
          "x": "2025年11月，国有大行集体下架5年期大额存单，彼时压降高息负债、稳定净息差是全行业共识，净息差已降至历史低位。"
        },
        {
          "t": "为何回归",
          "x": "2026年五年期存款到期规模达5至6万亿元，银行需提前锁定长期负债缓解久期错配；股份行同类产品最高达1.8%，但高息额度极稀缺。"
        }
      ],
      "interpretations": [
        {
          "q": "银行为什么刚下架又急着把长期存款“请回来”？",
          "naive": "以为利率要触底反弹了。",
          "lens": "货币政策",
          "lensId": "econ_monetary_policy",
          "body": "<b>货币政策</b>环境里，利率下行让银行敢于用约1.6%的成本锁住五年期资金。这轮回归并非利率拐点，而是银行在“控息差”与“稳负债”之间的阶段性平衡——用较低成本提前锁定长期资金，应对未来资产端再投资收益率下降的压力。",
          "aha": "不是利息要涨，是银行想用便宜价钱把你的钱留住久一点。"
        },
        {
          "q": "大额存单的来来去去，和普通人有什么关系？",
          "naive": "以为只是银行内部的科目游戏。",
          "lens": "宏观经济学",
          "lensId": "econ_macro",
          "body": "<b>宏观经济学</b>看的是资金在全社会的时间配置。居民手握的存款，是银行放贷支持实体经济的源头；当银行“缺负债”、净息差承压，便会调整存款品种与利率，间接影响每个人的理财与房贷成本。宏观政策的一丝摆动，最终落在你存单的利率上。",
          "aha": "你那张存单的利率，连着整个经济的资金水位。"
        }
      ],
      "theories": [
        {
          "id": "econ_monetary_policy",
          "label": "货币政策"
        },
        {
          "id": "econ_macro",
          "label": "宏观经济学"
        }
      ],
      "essayTopics": [
        {
          "id": "gain_loss",
          "label": "得与失"
        },
        {
          "id": "risk_uncertain",
          "label": "风险与不确定"
        }
      ],
      "essayQuote": "四大行5年期大额存单“去而复返”，距离集体下架还不到一年。这不是利率拐点，而是银行在净息差承压下的阶段性腾挪：用约1.6%的低成本锁住五年期资金，缓解久期错配。对普通人而言，它提醒我们——存单利率的每一丝起伏，都连着宏观经济的资金水位。",
