      "essayQuote": "凌晨3点40的闹钟，和一条“北京大学”的短信，串起了一个母亲十八年的托举。邹品芝说自己是“三无人员”，却托出了两个女儿——一个行医、一个进北大。这个故事让人破防，是因为在阶层日益固化的焦虑里，它证明教育这条门还没完全关上；只是打开它的，常常是一位母亲扛了十八年的钢管。",
