      "title": "姚洋称“智商低于150搞不好数学”引争议：天赋与努力的教育思辨",
      "source": "科学网（新浪）",
      "url": "https://cj.sina.com.cn/articles/view/7879923018/1d5ae154a01901gwxs",
      "kicker": "教育 · 心理学",
      "gist": "北大教授姚洋在一场演讲中称“智商低于150搞不好数学，数学天赋是天生的、跟培养没关系”，引发广泛争议。支持者认为顶尖数学研究确有极高智力门槛，反对者担心陷入“唯智商论”消解努力意义；王虹获菲尔兹奖后也说“题该做不出来还是做不出来”，让这场关于天赋与勤勉的教育思辨持续升温。",
