      "essayQuote": "“智商低于150搞不好数学”——这句话扎心，是因为它把无数普通人的努力轻轻抹去。顶尖数学研究确有智力门槛，这不容否认；但把成就全归“天生”，却会让更多孩子早早给自己贴上“我不行”的标签。成长型思维告诉我们：天赋决定天花板，努力决定你能不能真的够到它。教育的意义，从来不是预言谁不行。",
